func newPreset() unsafe.Pointer { return unsafe.Pointer(new(homelayout.Preset)) }

func newNPreset(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]homelayout.Preset, n)))
}

func ptrPreset(p unsafe.Pointer, c int32) any {
	r := (*homelayout.Preset)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return &r.Name
	case 4:
		return &r.Description
	case 5:
		return &r.Layout
	case 6:
		return (*[]string)(unsafe.Pointer(&r.RoleIDs))
	case 7:
		return (*string)(unsafe.Pointer(&r.CoreResponsibility))
	case 8:
		return &r.IsOrgDefault
	case 9:
		return &r.Locked
	case 10:
		return (*int64)(unsafe.Pointer(&r.Priority))
	case 11:
		return (*string)(unsafe.Pointer(&r.CreatedBy))
	case 12:
		return &r.Version
	case 13:
		return &r.CreatedAt
	case 14:
		return &r.UpdatedAt
	}
	return nil
}

func valuePreset(p unsafe.Pointer, c int32) any {
	r := (*homelayout.Preset)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return r.Name
	case 4:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 5:
		if r.Layout == nil {
			return nil
		}
		return *r.Layout
	case 6:
		if r.RoleIDs == nil {
			return nil
		}
		return keel.Strings(r.RoleIDs)
	case 7:
		if r.CoreResponsibility == "" {
			return nil
		}
		return string(r.CoreResponsibility)
	case 8:
		return r.IsOrgDefault
	case 9:
		return r.Locked
	case 10:
		return int64(r.Priority)
	case 11:
		if r.CreatedBy == "" {
			return nil
		}
		return string(r.CreatedBy)
	case 12:
		return r.Version
	case 13:
		return r.CreatedAt
	case 14:
		return r.UpdatedAt
	}
	return nil
}

